# ✅ Two-Layer Knowledge Architecture
class WorkflowContext:
    """Temporary learning context for single workflow execution"""
    def __init__(self):
        self.lessons = []  # Session-specific, cleared after workflow
        self.iteration_metrics = {}

    def add_lesson(self, lesson: str, subtask_id: str):
        """Accumulate lessons during workflow"""
        self.lessons.append({
            "content": lesson,
            "source_subtask": subtask_id,
            "timestamp": datetime.now()
        })

    def clear(self):
        """Clear after workflow completion"""
        self.lessons.clear()
        self.iteration_metrics.clear()

class Orchestrator:
    def __init__(self, playbook_manager):
        self.playbook = playbook_manager  # Global, persistent
        self.workflow_context = None  # Created per workflow

    def execute_workflow(self, workflow):
        # Create temporary workflow context
        self.workflow_context = WorkflowContext()

        for subtask in workflow.subtasks:
            # Actor gets BOTH global playbook + workflow context
            context = {
                "playbook_patterns": self.playbook.get_relevant_bullets(subtask.query),
                "workflow_lessons": self.workflow_context.lessons
            }
            result = actor.execute(subtask, context)

        # After workflow: Reflector extracts high-value lessons for playbook
        reflector_insights = reflector.analyze(self.workflow_context)
        curator.integrate(reflector_insights, self.playbook)

        # Clear temporary context
        self.workflow_context.clear()
