# ✅ Iteration Tracking for Learning Validation
class WorkflowMetrics:
    def __init__(self):
        self.subtask_iterations = {}  # {subtask_id: iteration_count}

    def track_iteration(self, subtask_id, iteration_num):
        self.subtask_iterations[subtask_id] = iteration_num

    def calculate_learning_efficiency(self, baseline_subtask, current_subtask):
        baseline_iters = self.subtask_iterations[baseline_subtask]
        current_iters = self.subtask_iterations[current_subtask]

        efficiency = (baseline_iters - current_iters) / baseline_iters

        if efficiency < 0:
            raise LearningRegressionError(
                f"Learning failed: {current_subtask} required MORE iterations "
                f"({current_iters}) than baseline ({baseline_iters})"
            )

        return efficiency  # 0.5 = 50% improvement

# Usage in orchestrator
