# ✅ Over-Delivery Tracking and Threshold Validation
class OptimizationMetrics:
    # Evidence-based thresholds from workflow analysis
    THRESHOLDS = {
        "optimal_zone": (1.0, 1.5),  # 100-150% over target
        "caution_zone": (1.5, 2.0),  # 150-200% over target  
        "danger_zone": (2.0, float('inf'))  # >200% over target
    }

    @staticmethod
    def calculate_over_delivery(target: float, actual: float) -> float:
        """Returns over-delivery ratio (e.g., 1.35 = 135% of target)"""
        return actual / target

    @staticmethod
    def assess_quality(over_delivery: float, template_purpose: str) -> dict:
        """Assess optimization quality based on over-delivery"""
        if over_delivery < 1.0:
            return {"zone": "under_target", "action": "increase_optimization"}
        elif over_delivery <= 1.5:
            return {"zone": "optimal", "action": "approved", 
                    "evidence": "Monitor 135% praised"}
        elif over_delivery <= 2.0:
            return {"zone": "caution", "action": "review_required",
                    "risk": "approaching_danger_threshold"}
        else:
            return {"zone": "danger", "action": "reject",
                    "evidence": "Evaluator 238% raised concerns"}

# Usage in optimization workflow:
target_reduction = 0.50  # 50% target
actual_reduction = 0.67  # 67% achieved
over_delivery = OptimizationMetrics.calculate_over_delivery(
    target_reduction, actual_reduction
)  # Returns 1.34 (134%)

assessment = OptimizationMetrics.assess_quality(over_delivery, "validation")
print(f"Zone: {assessment['zone']}, Action: {assessment['action']}")
# Output: Zone: optimal, Action: approved
