# Template purpose classification system
class TemplatePurpose(Enum):
    TEACHING = "teaching"  # Evaluator, detailed patterns
    VALIDATION = "validation"  # Monitor, pass/fail checks

class OptimizationPolicy:
    POLICIES = {
        TemplatePurpose.TEACHING: {
            "max_ceiling": 1.5,  # 150% over target
            "preserve": ["code_examples", "rationale", "context"],
            "allow_summaries": False,
            "priority": "pedagogical_completeness"
        },
        TemplatePurpose.VALIDATION: {
            "max_ceiling": 2.0,  # 200% over target
            "preserve": ["criteria", "thresholds"],
            "allow_summaries": True,
            "priority": "decision_speed"
        }
    }

    @staticmethod
    def get_ceiling(purpose: TemplatePurpose, target_reduction: float):
        policy = OptimizationPolicy.POLICIES[purpose]
        return target_reduction * policy["max_ceiling"]

# Usage:
# Teaching template (Evaluator)
eval_ceiling = OptimizationPolicy.get_ceiling(TemplatePurpose.TEACHING, 0.5)
# Result: 0.75 max reduction (50% * 150%)

# Validation template (Monitor)  
monitor_ceiling = OptimizationPolicy.get_ceiling(TemplatePurpose.VALIDATION, 0.5)
# Result: 1.0 max reduction (50% * 200%)
